// Receives n8n's Error Trigger payload. Logs a single structured line; no secrets.
const data = $input.first().json;
const execution = data.execution || {};
const workflow = data.workflow || {};
const error = execution.error || data.trigger?.error || {};

const record = {
  source: 'n8n-error-workflow',
  workflowId: workflow.id || null,
  workflowName: workflow.name || 'unknown',
  node: execution.lastNodeExecuted || 'unknown',
  error: typeof error.message === 'string' ? error.message : String(error),
  executionId: execution.id || null,
  executionUrl: execution.url || null,
  at: new Date().toISOString(),
};

console.error(`[LendLoop][workflow-error] ${JSON.stringify(record)}`);
return [{ json: record }];
